export const getColumns = (currency: string) =>
	!storageCols
		? getInitialCols(currency)
		: getInitialCols(currency).sort((a, b) => {
				const aIndex = storageCols.findIndex((col) => col.id === a.id);
				const bIndex = storageCols.findIndex((col) => col.id === b.id);
				return aIndex - bIndex;
			});
